using Godot;
using Mechanica.Core.World;
using Mechanica.Game.Creations;
using Mechanica.Game.Net;
using FileAccess = Godot.FileAccess;

namespace Mechanica.Game.World;

/// <summary>
/// Streams the world in chunks and force-loads Creations (chunk 12), by applying a Core
/// <see cref="ChunkStreamer"/> to the scene every physics tick, before players and bodies move. Each
/// loaded chunk is a <see cref="TerrainChunk"/> generated by a <see cref="WorldGenerator"/> (chunk 19).
/// <list type="bullet">
/// <item>The host (and an offline game) streams for every player and parks and resumes the Creations it
/// is the authority for (D5), so a client's player always has ground under it on the host.</item>
/// <item>A client streams ground for its own player only. It never parks Creations: the host decides
/// what is simulated, and state sync (chunk 4b) shows the result.</item>
/// <item>The world is a pure function of its <see cref="WorldState"/> (seed and destroyed objects) and
/// the mods' world data, which the join handshake already checks. The host sends its state to each
/// client as it joins and every destroyed object as it happens; clients regenerate the same ground.</item>
/// </list>
/// </summary>
public partial class WorldStreamer : Node3D
{
    /// <summary>Where the tuning is read from.</summary>
    public const string DefaultSettingsPath = "res://data/streaming.json";

    private readonly Dictionary<ChunkCoord, TerrainChunk> _chunks = [];
    private readonly HashSet<ChunkCoord> _pending = [];

    /// <summary>The session, for this peer's role. Set before adding to the tree.</summary>
    public NetSession Session { get; init; } = null!;

    /// <summary>Players to stream around. Set before adding to the tree.</summary>
    public PlayerSync PlayerSync { get; init; } = null!;

    /// <summary>Creations to force-load, park and resume. Set before adding to the tree.</summary>
    public CreationWorld Creations { get; init; } = null!;

    /// <summary>Streamed around while there is no player yet, so the spawn has ground.</summary>
    public Func<Vector3> SpawnPoint { get; init; } = () => Vector3.Zero;

    /// <summary>World generation rules and POIs. Set before adding to the tree.</summary>
    public WorldGenData WorldGen { get; init; } = WorldGenData.Flat;

    /// <summary>Seed of the world this peer starts with; a client replaces it with the host's. Set before adding to the tree.</summary>
    public long Seed { get; init; }

    /// <summary>Host: destroyed objects to start with (a loaded save); used only when its seed is <see cref="Seed"/>.</summary>
    public WorldState? InitialState { get; init; }

    /// <summary>Tuning; null reads <see cref="DefaultSettingsPath"/> when the node starts.</summary>
    public StreamingSettings? Settings { get; set; }

    /// <summary>The streaming logic, once started.</summary>
    public ChunkStreamer Streamer { get; private set; } = null!;

    /// <summary>Generates the ground, once started.</summary>
    public WorldGenerator Generator { get; private set; } = null!;

    /// <summary>Seed and destroyed objects, once started.</summary>
    public WorldState State { get; private set; } = null!;

    /// <summary>
    /// Ground nodes of the loaded chunks. A chunk the streamer loads is built at once when a player or a
    /// Creation is on or near it, otherwise within a tick or a few (<see cref="StreamingSettings.ChunkBuildBudget"/>).
    /// </summary>
    public IReadOnlyDictionary<ChunkCoord, TerrainChunk> Chunks => _chunks;

    /// <summary>Client side: the host's world replaced the one this peer started with.</summary>
    public event Action? WorldReplaced;

    /// <summary>True when this peer decides which Creations are simulated.</summary>
    public bool StreamsCreations => Session.IsHost;

    /// <summary>Reads the tuning from <see cref="DefaultSettingsPath"/>.</summary>
    public static StreamingSettings LoadDefaultSettings()
    {
        using var file = FileAccess.Open(DefaultSettingsPath, FileAccess.ModeFlags.Read)
            ?? throw new InvalidOperationException($"Cannot open {DefaultSettingsPath}: {FileAccess.GetOpenError()}");
        return StreamingSettings.FromJson(file.GetAsText());
    }

    public override void _Ready()
    {
        ProcessPhysicsPriority = -200;
        Settings ??= LoadDefaultSettings();
        State = InitialState is { } loaded && loaded.Seed == Seed ? loaded : new WorldState(Seed);
        Generator = new WorldGenerator(WorldGen, Seed, Settings.WorldSize);
        Streamer = new ChunkStreamer(Settings);
        Creations.Removed += Streamer.Forget;
        Session.PeerReady += SendWorld;
        Step(0f);
    }

    public override void _ExitTree()
    {
        Creations.Removed -= Streamer.Forget;
        Session.PeerReady -= SendWorld;
    }

    public override void _PhysicsProcess(double delta) => Step((float)delta);

    /// <summary>The chunk holding a world position.</summary>
    public ChunkCoord ChunkAt(Vector3 position) => ChunkCoord.At(position.X, position.Z, Streamer.Settings.ChunkSize);

    /// <summary>Runs one streaming update now and applies it.</summary>
    public StreamingUpdate Step(float delta)
    {
        var local = Session.LocalPeer;
        IEnumerable<Player.PlayerController> streamed = StreamsCreations
            ? PlayerSync.Players.Values
            : PlayerSync.LocalPlayer is { } own ? [own] : [];
        var players = streamed.Select(p => p.GlobalPosition.ToNumerics()).ToList();
        if (players.Count == 0)
            players.Add(SpawnPoint().ToNumerics());
        var samples = StreamsCreations
            ? Creations.All.Where(c => c.AuthorityPeer == local).Select(c => Creations.Sample(c.Id)).ToList()
            : [];

        var update = Streamer.Update(delta, players, samples);
        foreach (var id in update.Park)
            Creations.Park(id);
        foreach (var chunk in update.Unload)
        {
            _pending.Remove(chunk);
            if (_chunks.Remove(chunk, out var node))
            {
                RemoveChild(node);
                node.QueueFree();
            }
        }
        _pending.UnionWith(update.Load);
        BuildPending(players, samples);
        foreach (var id in update.Resume)
            Creations.Resume(id);
        foreach (var id in update.FellAsleep)
            Creations.Sleep(id);
        return update;
    }

    // Builds the chunks under players and force-loaded Creations now, then others nearest a player first
    // within the per-tick budget. Building a chunk takes milliseconds, and a client joining or a player
    // crossing into new ground asks for many at once.
    private void BuildPending(List<System.Numerics.Vector3> players, List<CreationSample> samples)
    {
        if (_pending.Count == 0)
            return;
        var settings = Streamer.Settings;
        var margin = new System.Numerics.Vector3(settings.GroundMargin);
        var urgent = players.SelectMany(p => Streamer.ChunksOf(WorldBounds.Around(p, margin)))
            .Concat(samples.SelectMany(c => Streamer.ChunksOf(c.Bounds.Expand(settings.CreationBuffer + settings.GroundMargin))))
            .Where(_pending.Contains)
            .ToHashSet();
        foreach (var chunk in urgent)
            Build(chunk);
        var started = System.Diagnostics.Stopwatch.GetTimestamp();
        var budget = TimeSpan.FromSeconds(settings.ChunkBuildBudget);
        var queue = _pending.OrderBy(c => players.Min(p => Distance(c, p))).ToList();
        foreach (var chunk in queue)
        {
            Build(chunk);
            if (System.Diagnostics.Stopwatch.GetElapsedTime(started) >= budget)
                break;
        }
    }

    private void Build(ChunkCoord chunk)
    {
        _pending.Remove(chunk);
        var node = new TerrainChunk { Data = Generator.GenerateChunk(chunk, Streamer.Settings.ChunkSize), State = State };
        AddChild(node);
        _chunks[chunk] = node;
    }

    // Distance (x/z) from a player to a chunk's centre.
    private float Distance(ChunkCoord chunk, System.Numerics.Vector3 player)
    {
        var size = Streamer.Settings.ChunkSize;
        var (x, z) = chunk.Origin(size);
        return System.Numerics.Vector2.Distance(new(x + size / 2f, z + size / 2f), new(player.X, player.Z));
    }

    /// <summary>
    /// Host side: destroys a scattered object (a felled tree, a mined rock node) for every peer. Returns
    /// false on a client, or when the world has no such object or it is already gone.
    /// </summary>
    public bool DestroyObject(WorldObjectId id)
    {
        if (!Session.IsHost || Generator.Find(id) is null || !State.Destroy(id))
            return false;
        RefreshChunkHolding(id);
        if (Session.State == NetSession.SessionState.Hosting)
            Rpc(MethodName.ObjectDestroyed, id.ToString());
        return true;
    }

    private void SendWorld(int peer) => RpcId(peer, MethodName.ReceiveWorld, State.ToJson());

    /// <summary>Host → joining client: the world's seed and destroyed objects.</summary>
    [Rpc(MultiplayerApi.RpcMode.Authority, TransferMode = MultiplayerPeer.TransferModeEnum.Reliable)]
    private void ReceiveWorld(string stateJson)
    {
        if (Session.IsHost)
            return;
        WorldState state;
        try
        {
            state = WorldState.FromJson(stateJson);
        }
        catch (FormatException e)
        {
            GD.PushError($"[world] host sent an unreadable world: {e.Message}");
            return;
        }
        State = state;
        if (state.Seed != Generator.Seed)
        {
            // A new world: drop every chunk and stream again from scratch.
            Generator = new WorldGenerator(WorldGen, state.Seed, Streamer.Settings.WorldSize);
            foreach (var node in _chunks.Values)
            {
                RemoveChild(node);
                node.QueueFree();
            }
            _chunks.Clear();
            _pending.Clear();
            Creations.Removed -= Streamer.Forget;
            Streamer = new ChunkStreamer(Streamer.Settings);
            Creations.Removed += Streamer.Forget;
        }
        else
        {
            foreach (var node in _chunks.Values)
            {
                node.State = State;
                node.RefreshObjects();
            }
        }
        GD.Print($"[world] joined world {state.Seed} ({state.Destroyed.Count} objects destroyed)");
        Step(0f);
        WorldReplaced?.Invoke();
    }

    /// <summary>Host → clients: an object was destroyed.</summary>
    [Rpc(MultiplayerApi.RpcMode.Authority, TransferMode = MultiplayerPeer.TransferModeEnum.Reliable)]
    private void ObjectDestroyed(string id)
    {
        if (Session.IsHost || !WorldObjectId.TryParse(id, out var parsed) || !State.Destroy(parsed))
            return;
        RefreshChunkHolding(parsed);
    }

    private void RefreshChunkHolding(WorldObjectId id)
    {
        foreach (var node in _chunks.Values)
        {
            if (node.Holds(id))
                node.RefreshObjects();
        }
    }
}
